<?php
require_once __DIR__.'/helpers.php';require_once __DIR__.'/hr_organization_lib.php';require_once __DIR__.'/erp_migrations.php';require_once __DIR__.'/app/Services/RoutingService.php';require_login();gt_run_org_migrations($pdo);erp_run_phase1_migrations($pdo);$user=current_user($pdo)?:[];$uid=(int)$user['id'];if(!erp_user_can($pdo,$user,'erp.routings.view')){http_response_code(403);exit('Sem permissão para consultar routings.');}$articleId=(int)($_GET['article_id']??$_POST['article_id']??0);$articleStmt=$pdo->prepare('SELECT id,code,description FROM erp_finished_products WHERE id=?');$articleStmt->execute([$articleId]);$article=$articleStmt->fetch(PDO::FETCH_ASSOC);if(!$article){http_response_code(404);exit('Artigo não encontrado.');}$service=new RoutingService($pdo);$ok=$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'&&validate_csrf_or_abort(false)){try{$action=(string)($_POST['action']??'');if($action==='activate'){if(!erp_user_can($pdo,$user,'erp.routings.activate'))throw new RuntimeException('Sem permissão para ativar routings.');$service->activateVersion((int)$_POST['version_id'],(string)($_POST['effective_from']??''),$uid);$ok='Versão ativada; a versão anteriormente ativa foi arquivada.';}else{if(!erp_user_can($pdo,$user,'erp.routings.edit'))throw new RuntimeException('Sem permissão para editar routings.');if($action==='new_version'){$versionId=$service->createVersion($articleId,$uid,(int)($_POST['source_version_id']??0)?:null);$ok='Nova versão em rascunho criada.';}elseif($action==='add_step'){$service->addStep((int)$_POST['version_id'],(int)$_POST['operation_id'],$_POST,$uid);$ok='Operação adicionada com predefinições copiadas.';}elseif($action==='move'){$service->moveStep((int)$_POST['step_id'],(string)$_POST['direction'],$uid);$ok='Sequência atualizada.';}}}catch(Throwable$e){$error=$e->getMessage();}}
$versionsStmt=$pdo->prepare('SELECT v.*,u.name created_name,(SELECT COUNT(*) FROM erp_article_routing_steps s WHERE s.routing_version_id=v.id) step_count FROM erp_article_routing_versions v JOIN erp_article_routings r ON r.id=v.routing_id LEFT JOIN users u ON u.id=v.created_by WHERE r.finished_product_id=? ORDER BY v.version_no DESC');$versionsStmt->execute([$articleId]);$versions=$versionsStmt->fetchAll(PDO::FETCH_ASSOC);$selectedVersionId=(int)($_GET['version_id']??$_POST['version_id']??($versions[0]['id']??0));$steps=[];if($selectedVersionId){$s=$pdo->prepare('SELECT s.*,o.code,o.name,w.name work_center_name,m.code machine_code FROM erp_article_routing_steps s JOIN erp_operations o ON o.id=s.operation_id LEFT JOIN erp_work_centers w ON w.id=s.work_center_id LEFT JOIN erp_machines m ON m.id=s.primary_machine_id WHERE s.routing_version_id=? ORDER BY s.sort_order');$s->execute([$selectedVersionId]);$steps=$s->fetchAll(PDO::FETCH_ASSOC);}$operations=$pdo->query('SELECT id,code,name FROM erp_operations WHERE is_active=1 ORDER BY code')->fetchAll(PDO::FETCH_ASSOC);$machines=$pdo->query('SELECT id,code,name FROM erp_machines WHERE is_active=1 AND deleted_at IS NULL ORDER BY code')->fetchAll(PDO::FETCH_ASSOC);$activeVersion=null;foreach($versions as$v)if((int)$v['id']===$selectedVersionId)$activeVersion=$v;$differences=[];if($activeVersion&&!empty($activeVersion['based_on_version_id'])){$old=$pdo->prepare('SELECT operation_no,operation_id,setup_time,run_value,calculation_unit,operators_count FROM erp_article_routing_steps WHERE routing_version_id=? ORDER BY sort_order');$old->execute([(int)$activeVersion['based_on_version_id']]);$before=$old->fetchAll(PDO::FETCH_ASSOC);$after=array_map(static function($s){return array_intersect_key($s,array_flip(['operation_no','operation_id','setup_time','run_value','calculation_unit','operators_count']));},$steps);$max=max(count($before),count($after));for($i=0;$i<$max;$i++){if(($before[$i]??null)!==($after[$i]??null))$differences[]='Etapa '.($i+1).' alterada';}}$pageTitle='Routing · '.$article['code'];require __DIR__.'/partials/header.php';?>
<div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-start mb-3"><div><a href="erp.php?page=articles&article_id=<?=$articleId?>" class="small">← Artigo</a><h1 class="h3 mb-1">Routing · <?=h($article['code'])?></h1><p class="text-muted"><?=h($article['description'])?></p></div><?php if(erp_user_can($pdo,$user,'erp.routings.edit')):?><form method="post"><?=csrf_input()?><input type="hidden" name="article_id" value="<?=$articleId?>"><input type="hidden" name="action" value="new_version"><input type="hidden" name="source_version_id" value="<?=$selectedVersionId?>"><button class="btn btn-primary"><?=$selectedVersionId?'Duplicar / nova versão':'Criar routing'?></button></form><?php endif;?></div><?php if($ok):?><div class="alert alert-success"><?=h($ok)?></div><?php endif;if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?>
<div class="row g-3"><div class="col-lg-3"><div class="card"><div class="card-header fw-semibold">Histórico de versões</div><div class="list-group list-group-flush"><?php if(!$versions):?><div class="list-group-item text-muted">Ainda sem routing.</div><?php endif;foreach($versions as$v):?><a class="list-group-item list-group-item-action <?=$selectedVersionId===$v['id']?'active':''?>" href="?article_id=<?=$articleId?>&version_id=<?=$v['id']?>"><div class="d-flex justify-content-between"><strong>Versão <?=$v['version_no']?></strong><span class="badge <?=$v['status']==='active'?'text-bg-success':($v['status']==='draft'?'text-bg-warning':'text-bg-secondary')?>"><?=h($v['status'])?></span></div><small><?=$v['step_count']?> etapas · <?=h((string)$v['effective_from'])?></small></a><?php endforeach;?></div></div></div>
<div class="col-lg-9"><?php if($activeVersion):?><?php if(!empty($activeVersion['based_on_version_id'])):?><div class="alert alert-light border"><strong>Diferenças para a versão de origem:</strong> <?= $differences?h(implode('; ',$differences)):'Sem diferenças nos parâmetros principais.' ?></div><?php endif;?><div class="card mb-3"><div class="card-body d-flex flex-wrap justify-content-between gap-2"><div><strong>Versão <?=$activeVersion['version_no']?></strong> · <?=$activeVersion['step_count']?> etapas<?php if($activeVersion['status']==='active'):?> <span class="badge text-bg-success">Ativa desde <?=h((string)$activeVersion['effective_from'])?></span><?php endif;?></div><?php if($activeVersion['status']==='draft'&&erp_user_can($pdo,$user,'erp.routings.activate')):?><form method="post" class="d-flex gap-2" onsubmit="return confirm('Ativar esta versão e arquivar a versão ativa atual?')"><?=csrf_input()?><input type="hidden" name="article_id" value="<?=$articleId?>"><input type="hidden" name="action" value="activate"><input type="hidden" name="version_id" value="<?=$selectedVersionId?>"><input class="form-control form-control-sm" type="date" name="effective_from" value="<?=date('Y-m-d')?>" required><button class="btn btn-sm btn-success">Ativar versão</button></form><?php endif;?></div></div>
<div class="card mb-3"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Ordem</th><th>Operação</th><th>Centro / máquina</th><th>Operadores</th><th>Setup</th><th>Cadência</th><th>Espera + transf.</th><th></th></tr></thead><tbody><?php if(!$steps):?><tr><td colspan="8" class="text-center text-muted py-4">Routing vazio.</td></tr><?php endif;foreach($steps as$s):?><tr><td><?=$s['operation_no']?></td><td><strong><?=h($s['code'].' · '.$s['name'])?></strong><div class="small text-muted"><?=h((string)$s['specific_instructions'])?></div></td><td><?=h((string)$s['work_center_name'])?><br><small><?=h((string)$s['machine_code'])?></small></td><td><?=$s['operators_count']?></td><td><?=$s['setup_time']?> min</td><td><?=$s['run_value']?> <?=h($s['calculation_unit'])?> / base <?=$s['base_quantity']?></td><td><?=$s['wait_minutes']?> + <?=$s['transfer_minutes']?> min <?=$s['parallel_allowed']?'· paralelo':''?></td><td><?php if($activeVersion['status']==='draft'):?><form method="post" class="btn-group"><?=csrf_input()?><input type="hidden" name="article_id" value="<?=$articleId?>"><input type="hidden" name="action" value="move"><input type="hidden" name="version_id" value="<?=$selectedVersionId?>"><input type="hidden" name="step_id" value="<?=$s['id']?>"><button class="btn btn-sm btn-outline-secondary" name="direction" value="up">↑</button><button class="btn btn-sm btn-outline-secondary" name="direction" value="down">↓</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php if($activeVersion['status']==='draft'&&erp_user_can($pdo,$user,'erp.routings.edit')):?><div class="card"><div class="card-body"><h2 class="h5">Adicionar operação</h2><form method="post" class="row g-2"><?=csrf_input()?><input type="hidden" name="article_id" value="<?=$articleId?>"><input type="hidden" name="action" value="add_step"><input type="hidden" name="version_id" value="<?=$selectedVersionId?>"><div class="col-md-4"><label class="form-label">Operação</label><select class="form-select" name="operation_id" required><option value="">Selecione…</option><?php foreach($operations as$o):?><option value="<?=$o['id']?>"><?=h($o['code'].' · '.$o['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">N.º operação</label><input class="form-control" type="number" name="operation_no"></div><div class="col-md-3"><label class="form-label">Máquina principal</label><select class="form-select" name="primary_machine_id"><option value="">Predefinida</option><?php foreach($machines as$m):?><option value="<?=$m['id']?>"><?=h($m['code'].' · '.$m['name'])?></option><?php endforeach;?></select></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary w-100">Adicionar e copiar parâmetros</button></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="confirm_duplicate" value="1"> Confirmo que uma repetição desta operação é intencional</label></div></form></div></div><?php endif;endif;?></div></div></div><?php require __DIR__.'/partials/footer.php';?>
